package com.senniaf.match.iso25010.eficiencia;
import com.senniaf.match.model.*; import com.senniaf.match.model.enums.*; import com.senniaf.match.repository.*; import com.senniaf.match.service.ScoringService; import org.junit.jupiter.api.*; import org.junit.jupiter.params.ParameterizedTest; import org.junit.jupiter.params.provider.ValueSource; import java.time.Duration; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ScoringEficienciaIsoTest { @ParameterizedTest @ValueSource(ints={1,10,25,50,100,200,300,400,500,1000}) void EFI01_calculoLoteDentroDelUmbral(int lote){var s=new ScoringService(mock(PerfilNinoRepository.class),mock(PerfilFamiliaRepository.class),mock(DecisionComiteRepository.class),mock(PesosScoringRepository.class));var n=new PerfilNino();n.setEdad(8);n.setTieneHermanos(SiNo.NO);n.setCondicionesSalud(List.of());var f=new PerfilFamilia();f.setEdadMinimaAceptada(1);f.setEdadMaximaAceptada(17);f.setDisponibilidadViaje(DisponibilidadViaje.ALTA);f.setDisposicionHermanos(DisposicionHermanos.DISPUESTA);var p=new PesosScoring();assertTimeoutPreemptively(Duration.ofMillis(1000),()->{for(int i=0;i<lote;i++)s.candidato(n,f,p);});}}
